-- T13624 (T12997) — a conflict keeps this store's pre-merge values.
--
-- _sync_conflict.local_json: canonical JSON {column: wire value} of the
--   conflicting, non-secret columns as this store held them just before the
--   merge (references as uids). For an incoming-applied conflict the merge
--   overwrote them, and `cleo cloud conflicts resolve --keep mine` re-asserts
--   them from here. NULL for conflicts recorded before this column, or when
--   the row was not live.
--
-- Local-only, both stores.
--
-- Do not edit this file once applied: its hash is recorded per store.
ALTER TABLE _sync_conflict ADD COLUMN local_json TEXT;
